class JSONPlaceholderAPI:
    def __init__(self):
        self.base_url = "https://jsonplaceholder.typicode.com"
        self.session = requests.Session()
        self.session.headers.update(
            {"User-Agent": "MyApp/1.0", "Accept": "application/json"}
        )

    def get_posts(self, limit=None):
        """Get all posts or limited number"""
        params = {"_limit": limit} if limit else {}
        response = self.session.get(f"{self.base_url}/posts", params=params)
        response.raise_for_status()
        return response.json()

    def get_post(self, post_id):
        """Get single post by ID"""
        response = self.session.get(f"{self.base_url}/posts/{post_id}")
        response.raise_for_status()
        return response.json()

    def create_post(self, title, body, user_id=1):
        """Create new post"""
        data = {"title": title, "body": body, "userId": user_id}
        response = self.session.post(f"{self.base_url}/posts", json=data)
        response.raise_for_status()
        return response.json()

    def close(self):
        self.session.close()

# Use the API client
try:
    api = JSONPlaceholderAPI()

    # Get posts
    posts = api.get_posts(limit=3)
    print(f"Retrieved {len(posts)} posts")

    # Get single post
    post = api.get_post(1)
    print(f"\nPost 1: {post['title']}")

    # Create post
    new_post = api.create_post("Test Post", "Test content")
    print(f"\nCreated post with ID: {new_post['id']}")

finally:
    api.close()

print("\n" + "=" * 70)
print("All examples completed!")
print("=" * 70)
